SELECT ,
       p.offlined_by, p.offlined_at, o.username as offliner_username
FROM posts p
LEFT JOIN users u ON p.author_id = u.id
LEFT JOIN users o ON p.offlined_by = o.id
LEFT JOIN categories c ON p.category_id = c.id

    AND p.status = #{status}
    AND p.author_id = #{authorId}
    AND p.category_id = #{categoryId}

        AND p.title LIKE CONCAT('%', , '%') ESCAPE '\\'


        AND p.created_at >= #{startDate}


        AND p.created_at < DATE_ADD(#{endDate}, INTERVAL 1 DAY)


ORDER BY p.created_at DESC

SELECT 
FROM posts p
LEFT JOIN users u ON p.author_id = u.id
LEFT JOIN categories c ON p.category_id = c.id

    p.author_id = #{authorId}
    AND p.status IN ('published', 'offline')

        AND p.title LIKE CONCAT('%', , '%') ESCAPE '\\'

    AND YEAR(p.updated_at) = #{year}
    AND MONTH(p.updated_at) = #{month}

ORDER BY p.updated_at DESC
